  "groups": {"drop":{"title":"The drop","checks":[{"k":"droptrack","t":"I tracked where other squads landed","m":"Didn't track other squads","card":"1.12"},{"k":"dropplan","t":"I landed with a plan: where my gun is and where we exit","m":"Landed with no plan","card":"1.12"},{"k":"dropnear","t":"I landed close enough to help my teammates","m":"Landed too far from my team","card":"1.12"},{"k":"dropgun","t":"I had a gun before I took a fight","m":"Fought without a gun","card":"1.12"},{"k":"dropleave","t":"We left when the drop went bad, instead of staying to die","m":"Stayed when the drop went bad","card":"1.12"},{"k":"dropsplit","t":"Uncontested, we split up and pinged our buildings","m":"Didn't split and ping buildings","card":"1.12"}]},"position":{"title":"Position and rotation","checks":[{"k":"early","t":"We moved before the ring forced us","m":"Moved late","card":"1.7"},{"k":"cover","t":"Our path had cover","m":"No cover","card":"1.2"},{"k":"side","t":"We knew if we were on the strong or weak side","m":"Didn't know strong or weak side","card":"0.3"},{"k":"height","t":"I kept height, and didn't drop off it just because a teammate did","hint":"Follow the plan, not the person. Dropping off height gives away your advantage.","m":"Gave up height","card":"7.1"},{"k":"count","t":"I knew how many enemies we were fighting","m":"Didn't know how many","card":"7.3"},{"k":"ready","t":"I was healed, shielded and reloaded before it started","m":"Not healed or reloaded","card":"3.1"},{"k":"behind","t":"Someone checked behind us for a third party","m":"Nobody watched our back","card":"2.3"},{"k":"split","t":"I took a different angle than my teammate (no stacking)","m":"Stacked on a teammate","card":"3.3"},{"k":"healcover","t":"I healed where a teammate could cover me, or covered theirs","m":"Healed with no cover","card":"5.7"}]},"comms":{"title":"Comms","checks":[{"k":"saw","t":"I called what I saw: where, how many, how hurt","m":"Didn't call what I saw","card":"5.2"},{"k":"doing","t":"I said what I was doing before I did it","hint":"\"Swinging left.\" \"Healing.\" \"Resetting to the rock.\"","m":"Didn't say what I was doing","card":"5.2"},{"k":"ping","t":"I pinged enemies instead of only saying them","m":"Didn't ping them","card":"5.2"},{"k":"knew","t":"My teammates knew where I was","m":"Team didn't know where I was","card":"5.2"},{"k":"calls","t":"Calls were made, and we acted on them","m":"No calls, or ignored them","card":"5.2"},{"k":"plancall","t":"Someone called the plan before we moved","m":"No plan called","card":"5.2"}]},"fight":{"title":"Gunfight","checks":[{"k":"head","t":"My crosshair stayed at head height","m":"Crosshair off head height","card":"4.12"},{"k":"preaim","t":"I pre-aimed where they came out","m":"Didn't pre-aim","card":"4.4"},{"k":"peek","t":"I info-peeked before I swung","m":"No info-peek first","card":"4.8"},{"k":"coverpeek","t":"I shot from cover and didn't stand in the open","m":"Shot from the open","card":"4.16"},{"k":"small","t":"I made one small play, then backed up","m":"Made too big a play","card":"3.5"},{"k":"bigdmg","t":"I only pushed hard off big damage or a knock","m":"Pushed without damage","card":"3.5"},{"k":"reload","t":"I reloaded and healed behind cover","m":"Reloaded or healed in the open","card":"4.10"},{"k":"sync","t":"We pushed together off a teammate's knock","m":"Pushed out of sync","card":"5.4"},{"k":"resettimer","t":"We left a poke fight that went nowhere within a minute","m":"Stayed in a poke fight","card":"3.10"},{"k":"wide","t":"I wide-swung instead of re-peeking the same tight angle","hint":"Swing wide and fast so they see you late, from a new spot.","m":"Didn't wide swing","card":"4.2"},{"k":"strafe","t":"I strafed with a plan in the duel instead of standing still","m":"Stood still in the duel","card":"9.1"},{"k":"decide","t":"I decided fast and committed, no half-push","m":"Hesitated or half-committed","card":"6.10"}]},"kit":{"title":"Kit and grenades","checks":[{"k":"tac","t":"I used my tactical in this fight","legendHint":true,"m":"Didn't use my tactical","card":"3.4"},{"k":"ult","t":"I used my ultimate, or had a reason to save it","legendHint":true,"m":"Didn't use my ult","card":"3.4"},{"k":"nades","t":"I threw my grenades before I went down","hint":"Tap N/A if you had none.","m":"No nades","card":"3.6"},{"k":"utilfirst","t":"I used utility before pushing, not after","m":"Pushed before utility","card":"3.6"}]}},
