"themes": [
  {"id":"team","name":"Stay connected to your team","line":"Stay where you can help. Split angles, never stack. Say what you're doing before you do it.","not":"Close isn't stacked: take a different angle than your teammate (3.3). On an uncontested drop, split up and loot your own building (1.12).","cards":["3.3","5.4","5.2","5.7","7.1","1.12"],"reasons":["landapart","farteam","stacked","spacing","alone","comms"],"checks":["dropnear","split","healcover","knew","doing","plancall","sync","saw","ping","calls"]},
  {"id":"edge","name":"Only fight with an edge","line":"Before every fight, call strong side or weak side, and why. No edge, no fight.","not":"Weak side isn't a lost cause: reset and wait for them to overextend instead of swinging into it (0.4).","cards":["0.3","0.4","0.1","0.1a","3.7","7.3"],"reasons":["noedge"],"checks":["side","count"]},
  {"id":"reset","name":"One play, then reset","line":"Swing, do one thing, back up, pop a cell. Push hard only off big damage.","not":"Off a knock or big damage, don't back up: decide fast and push together (3.5, 6.10).","cards":["3.5","3.2","3.1","3.10","6.10"],"reasons":["overstay","push"],"checks":["small","bigdmg","resettimer","ready"]},
  {"id":"rotate","name":"Rotate early, scan early","line":"Move with a reason before the ring forces you. Scan the next ring as early as you can.","not":"Early isn't random: no reason to move, no move (1.1).","cards":["1.1","1.7","1.8","0.1b","1.2","1.6"],"reasons":["ring","late","endgame"],"checks":["early","cover"]},
  {"id":"third","name":"Watch for the third party","line":"Every fight, ask where the third team comes from. Check behind you on every heal.","not":"You can be the third team too: wait until they're committed, then move (2.4).","cards":["2.2","2.3","5.1","5.8","2.4","2.1"],"reasons":["thirdparty","flanked","healing"],"checks":["behind"]},
  {"id":"space","name":"Hold your space","line":"Keep height and cover. If they crack you right now, can you back off and heal?","not":"Bailing too early loses space too: it's one of the three ways to lose it (7.1).","cards":["7.2","4.1","1.4","7.1","4.10"],"reasons":["height","open"],"checks":["height","reload"]},
  {"id":"gunfight","name":"Peek smart","line":"Crosshair at head height. Info peek first, then swing. Shoot from cover.","not":"Already have the shot? Plant and shoot; don't move without a reason (4.7).","cards":["4.12","4.8","4.2","4.16","4.4","4.7"],"reasons":["gunfight"],"checks":["head","preaim","peek","coverpeek","wide"]},
  {"id":"aim","name":"Win the aim duel","line":"Strafe with a plan, eyes on them, and shoot the one who isn't shooting you.","not":"Don't fix a bad night by changing your settings (9.11).","cards":["9.1","9.2","9.3","9.6","9.8","4.18"],"reasons":["aim"],"checks":["strafe"]},
  {"id":"kit","name":"Use your kit and grenades","line":"Tactical or a nade before every push. Throw your nades before you go down.","not":"Saving your ultimate is fine when you have a reason for it.","cards":["3.6","3.4","1.3"],"reasons":["util"],"checks":["tac","ult","nades","utilfirst"]},
  {"id":"drop","name":"Land with a plan","line":"Pick your gun spot and your exit before you jump. Track who lands near you.","not":"If the drop goes bad, leave instead of staying to die.","cards":["1.12","1.5","1.6"],"reasons":["drop"],"checks":["droptrack","dropplan","dropgun","dropleave","dropsplit"]},
  {"id":"head","name":"Keep your head","line":"One slow breath before the fight. Miss or get cracked: say \"next\" and make the next play.","not":"Judge the decision, not the result: a good call can still lose a fight (6.7).","cards":["6.5","6.4","6.7","6.10","6.6","9.9"],"reasons":["froze","tilt"],"checks":["decide","breath"]}
],
